using System.Security.Claims;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Html;
using Microsoft.AspNetCore.Mvc.Rendering;

namespace BaseMVC.WebUI.Navigation;

/// <summary>Which admin modules the current user may open; drives the admin sidebar and the public "Quản trị" link.</summary>
public sealed record NavAccess(
    bool Roles, bool Permissions, bool Audit, bool Users, bool Faculties, bool Students, bool ExamTypes, bool Exams)
{
    public bool System => Roles || Permissions || Users || Audit;
    public bool Data => Faculties || Students || ExamTypes || Exams;
    public bool Any => System || Data;

    public static async Task<NavAccess> GetAsync(IAuthorizationService authorization, ClaimsPrincipal user)
    {
        if (user.Identity?.IsAuthenticated != true)
            return new NavAccess(false, false, false, false, false, false, false, false);

        async Task<bool> Can(string policy) => (await authorization.AuthorizeAsync(user, resource: null, policy)).Succeeded;
        return new NavAccess(
            await Can("Permissions.Roles.Read"), await Can("Permissions.Access.Read"), await Can("Permissions.Audit.Read"),
            await Can("Permissions.Users.Read"), await Can("Permissions.Faculties.Read"), await Can("Permissions.Students.Read"), await Can("Permissions.ExamTypes.Read"), await Can("Permissions.Exams.Read"));
    }
}

