    public static IHtmlContent Icon(string name, string cssClass = "size-4") =>
        new HtmlString(
            $"<svg xmlns=\"http://www.w3.org/2000/svg\" class=\"{cssClass} shrink-0\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\" stroke-width=\"1.75\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"{Icons[name]}\" /></svg>");

    public static bool IsActive(ViewContext viewContext, params string[] controllers)
    {
        var current = viewContext.RouteData.Values["controller"]?.ToString() ?? string.Empty;
        return controllers.Any(controller => string.Equals(controller, current, StringComparison.OrdinalIgnoreCase));
    }
